def deduplicate_stock_items(apps, schema_editor):
    """ادغام ردیف‌های هم‌محصول در یک انبار پیش از حذف برند و اعمال یکتایی (product, warehouse)."""
    StockItem = apps.get_model('purchases', 'StockItem')
    StockTransaction = apps.get_model('purchases', 'StockTransaction')
    WarehouseVoucherItem = apps.get_model('purchases', 'WarehouseVoucherItem')
    OfficerAssignment = apps.get_model('purchases', 'OfficerAssignment')
    WarehouseRequestItem = apps.get_model('purchases', 'WarehouseRequestItem')
    StockRequestItem = apps.get_model('purchases', 'StockRequestItem')

    grouped = {}
    for si in StockItem.objects.order_by('id'):
        grouped.setdefault((si.product_id, si.warehouse_id), []).append(si)

    for items in grouped.values():
        if len(items) <= 1:
            continue
        keeper = items[0]
        total_qty = keeper.quantity
        max_min = keeper.min_quantity
        dup_ids = []
        for dup in items[1:]:
            total_qty += dup.quantity
            if dup.min_quantity is not None and (max_min is None or dup.min_quantity > max_min):
                max_min = dup.min_quantity
            dup_ids.append(dup.id)
        keeper.quantity = total_qty
        keeper.min_quantity = max_min
        keeper.save(update_fields=['quantity', 'min_quantity'])

        for Model in (
            StockTransaction,
            WarehouseVoucherItem,
            OfficerAssignment,
            WarehouseRequestItem,
            StockRequestItem,
        ):
            Model.objects.filter(stock_item_id__in=dup_ids).update(stock_item_id=keeper.id)

        StockItem.objects.filter(id__in=dup_ids).delete()


